def num_islands(grid: list[list[str]]) -> int:
    rows, cols = len(grid), len(grid[0])
    islands = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != "1":
                continue
            islands += 1
            # Flood fill this island, sinking each cell as it is queued.
            grid[r][c] = "0"
            queue = deque([(r, c)])
            while queue:
