def longest_palindrome(s: str) -> str:
    n = len(s)
    best_start, best_len = 0, 1

    def expand(lo: int, hi: int) -> None:
        nonlocal best_start, best_len
        # Grow outward while both ends match.
        while lo >= 0 and hi < n and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        length = hi - lo - 1
        if length > best_len:
            best_start, best_len = lo + 1, length

    for center in range(n):
        expand(center, center)       # odd length, centered on a character
        expand(center, center + 1)   # even length, centered between two
    return s[best_start:best_start + best_len]

