def search(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:
            # Left half [lo, mid] is in sorted order.
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            # Right half [mid, hi] is in sorted order.
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

def top_k_frequent(nums: list[int], k: int) -> list[int]:
    counts = Counter(nums)
    # buckets[c] holds every value that occurs exactly c times.
    buckets = [[] for _ in range(len(nums) + 1)]
    for value, c in counts.items():
        buckets[c].append(value)
    result = []
    for c in range(len(nums), 0, -1):
        for value in buckets[c]:
            result.append(value)
            if len(result) == k:
                return result
    return result

