def max_sliding_window(nums: list[int], k: int) -> list[int]:
    window = deque()   # indices, values strictly decreasing front to back
    result = []
    for i, value in enumerate(nums):
        # Smaller older values can never be a future maximum.
        while window and nums[window[-1]] <= value:
            window.pop()
        window.append(i)
        if window[0] <= i - k:
            window.popleft()   # front index slid out of the window
        if i >= k - 1:
            result.append(nums[window[0]])
    return result

