class RandomizedSet:
    def __init__(self):
        self.values = []      # the elements, in arbitrary order
        self.where = {}       # value -> its index in self.values

    def insert(self, val: int) -> bool:
        if val in self.where:
            return False
        self.where[val] = len(self.values)
        self.values.append(val)
        return True

    def remove(self, val: int) -> bool:
        idx = self.where.pop(val, None)
        if idx is None:
            return False
        last = self.values.pop()
        if idx < len(self.values):
            # Fill the hole with the former last element.
            self.values[idx] = last
            self.where[last] = idx
        return True

    def getRandom(self) -> int:
        return random.choice(self.values)

