def word_break(s: str, wordDict: list[str]) -> bool:
    # Trie of dictionary words; "$" marks a word end.
    root = {}
    for w in wordDict:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = True

    n = len(s)
    can = [False] * (n + 1)   # can[i]: s[:i] splits into words
    can[0] = True
    for i in range(n):
        if not can[i]:
            continue
        node = root
        for j in range(i, n):
            node = node.get(s[j])
            if node is None:
                break
            if "$" in node:
                can[j + 1] = True
    return can[n]

