def exist(board: list[list[str]], word: str) -> bool:
    rows, cols = len(board), len(board[0])
    if len(word) > rows * cols:
        return False
    # Prune: the board must hold enough copies of every letter in word.
    have = Counter(ch for row in board for ch in row)
    if any(have[ch] < need for ch, need in Counter(word).items()):
        return False
    # Start from whichever end of the word is rarer on the board.
    if have[word[0]] > have[word[-1]]:
        word = word[::-1]

    def dfs(r: int, c: int, i: int) -> bool:
        if board[r][c] != word[i]:
            return False
        if i == len(word) - 1:
            return True
        board[r][c] = "#"                     # mark as used on this trace
        found = False
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and dfs(nr, nc, i + 1):
                found = True
                break
        board[r][c] = word[i]                 # restore
        return found

    return any(dfs(r, c, 0) for r in range(rows) for c in range(cols))

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.entries = {}                             # key -> [value, use count]
        self.buckets = defaultdict(OrderedDict)       # count -> keys, oldest first
        self.min_count = 0

    def _touch(self, key):
        entry = self.entries[key]
        count = entry[1]
        del self.buckets[count][key]
        if not self.buckets[count]:
            del self.buckets[count]
            if self.min_count == count:
                self.min_count = count + 1
        entry[1] = count + 1
        self.buckets[count + 1][key] = None

    def get(self, key: int) -> int:
        if key not in self.entries:
            return -1
        self._touch(key)
        return self.entries[key][0]

    def put(self, key: int, value: int) -> None:
        if key in self.entries:
            self.entries[key][0] = value
            self._touch(key)
            return
        if len(self.entries) >= self.capacity:
            # Evict the least recently used key among those with the fewest uses.
            bucket = self.buckets[self.min_count]
            victim, _ = bucket.popitem(last=False)
            if not bucket:
                del self.buckets[self.min_count]
            del self.entries[victim]
        self.entries[key] = [value, 1]
        self.buckets[1][key] = None
        self.min_count = 1

