        if reach >= last:
            return True
    return True

def calculate(s: str) -> int:
    total = 0     # sum of the finished terms
    last = 0      # value of the term being built
    num = 0
    op = "+"      # operator that precedes num
    for i, ch in enumerate(s):
        if ch.isdigit():
            num = num * 10 + (ord(ch) - 48)
        if (not ch.isdigit() and ch != " ") or i == len(s) - 1:
            if op == "+":
                total += last
                last = num
            elif op == "-":
                total += last
                last = -num
            elif op == "*":
                last *= num
            else:
                # Truncate toward zero; Python's // would floor.
                q = abs(last) // num
                last = q if last >= 0 else -q
            op = ch
            num = 0
    return total + last

