def asteroid_collision(asteroids: list[int]) -> list[int]:
    stack = []   # survivors so far, left to right
    for rock in asteroids:
        alive = True
        # A left mover may crash into right movers on top of the stack.
        while alive and rock < 0 and stack and stack[-1] > 0:
            if stack[-1] < -rock:
                stack.pop()          # the right mover explodes, keep going
            elif stack[-1] == -rock:
                stack.pop()          # both explode
                alive = False
            else:
                alive = False        # the new asteroid explodes
        if alive:
            stack.append(rock)
    return stack

